insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000001891', 'by the time', '/baɪ ðə taɪm/', 'conjunction', 'quando', 'By the time we arrived, the meeting had already started.', 'Quando chegamos, a reunião já tinha começado.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001892', 'no sooner...than', '/noʊ ˈsuːnər ðæn/', 'conjunction', 'mal... quando', 'No sooner had she sat down than the phone rang.', 'Mal ela tinha se sentado quando o telefone tocou.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001893', 'as soon as', '/æz suːn æz/', 'conjunction', 'assim que', 'Call me as soon as you get home.', 'Me ligue assim que você chegar em casa.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001894', 'once', '/wʌns/', 'conjunction', 'assim que', 'Once the report is finished, we can send it.', 'Assim que o relatório estiver pronto, podemos enviá-lo.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001895', 'while', '/waɪl/', 'conjunction', 'enquanto', 'She read a book while waiting for the bus.', 'Ela leu um livro enquanto esperava o ônibus.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001896', 'beforehand', '/bɪˈfɔːrhænd/', 'adverb', 'de antemão', 'It is better to prepare beforehand.', 'É melhor se preparar de antemão.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001897', 'in the meantime', '/ɪn ðə ˈmiːntaɪm/', 'phrase', 'enquanto isso', 'Dinner will be ready soon. In the meantime, relax.', 'O jantar vai ficar pronto logo. Enquanto isso, relaxe.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001898', 'eventually', '/ɪˈventʃuəli/', 'adverb', 'eventualmente', 'Eventually, they found a solution to the problem.', 'Eventualmente, eles encontraram uma solução para o problema.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001899', 'immediately', '/ɪˈmiːdiətli/', 'adverb', 'imediatamente', 'She left the office immediately after the call.', 'Ela saiu do escritório imediatamente depois da ligação.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001900', 'shortly after', '/ˈʃɔːrtli ˈæftər/', 'phrase', 'logo depois', 'Shortly after the announcement, the stock price rose.', 'Logo depois do anúncio, o preço da ação subiu.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001901', 'all of a sudden', '/ɔːl əv ə ˈsʌdən/', 'phrase', 'de repente', 'All of a sudden, the lights went out.', 'De repente, as luzes se apagaram.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001902', 'from then on', '/frʌm ðen ɒn/', 'phrase', 'a partir daquele momento', 'From then on, everything changed for the better.', 'A partir daquele momento, tudo mudou para melhor.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001903', 'up until', '/ʌp ənˈtɪl/', 'preposition', 'até', 'Up until last year, she had never traveled abroad.', 'Até o ano passado, ela nunca tinha viajado para o exterior.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001904', 'ever since', '/ˈevər sɪns/', 'phrase', 'desde então', 'They met in college, and ever since, they have been best friends.', 'Eles se conheceram na faculdade, e desde então, são melhores amigos.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001905', 'in due course', '/ɪn djuː kɔːrs/', 'phrase', 'no devido tempo', 'The results will be announced in due course.', 'Os resultados serão anunciados no devido tempo.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001906', 'sooner or later', '/ˈsuːnər ɔːr ˈleɪtər/', 'phrase', 'mais cedo ou mais tarde', 'Sooner or later, the truth always comes out.', 'Mais cedo ou mais tarde, a verdade sempre aparece.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001907', 'at that point', '/æt ðæt pɔɪnt/', 'phrase', 'naquele momento', 'At that point, nobody knew what would happen next.', 'Naquele momento, ninguém sabia o que aconteceria a seguir.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001908', 'at the same time', '/æt ðə seɪm taɪm/', 'phrase', 'ao mesmo tempo', 'You cannot cook and answer emails at the same time.', 'Você não pode cozinhar e responder e-mails ao mesmo tempo.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001909', 'simultaneously', '/ˌsaɪmənˈteɪniəsli/', 'adverb', 'simultaneamente', 'The two events happened simultaneously.', 'Os dois eventos aconteceram simultaneamente.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001910', 'gradually', '/ˈɡrædʒuəli/', 'adverb', 'gradualmente', 'The company gradually expanded into new markets.', 'A empresa se expandiu gradualmente para novos mercados.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001911', 'abruptly', '/əˈbrʌptli/', 'adverb', 'abruptamente', 'The meeting ended abruptly.', 'A reunião terminou abruptamente.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001912', 'henceforth', '/ˌhensˈfɔːrθ/', 'adverb', 'doravante', 'Henceforth, all reports must be submitted online.', 'Doravante, todos os relatórios devem ser enviados online.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001913', 'previously', '/ˈpriːviəsli/', 'adverb', 'anteriormente', 'The building was previously used as a warehouse.', 'O prédio era anteriormente usado como depósito.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001914', 'afterwards', '/ˈæftərwərdz/', 'adverb', 'depois', 'They had dinner and went to the cinema afterwards.', 'Eles jantaram e foram ao cinema depois.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001915', 'in retrospect', '/ɪn ˈretrəspekt/', 'phrase', 'em retrospecto', 'In retrospect, it was the right decision.', 'Em retrospecto, foi a decisão certa.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001916', 'at first', '/æt fɜːrst/', 'phrase', 'no início', 'At first, the plan seemed too risky.', 'No início, o plano parecia arriscado demais.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001917', 'in the end', '/ɪn ðə end/', 'phrase', 'no final', 'In the end, everything worked out fine.', 'No final, tudo deu certo.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001918', 'without delay', '/wɪˈðaʊt dɪˈleɪ/', 'phrase', 'sem demora', 'Please respond without delay.', 'Por favor, responda sem demora.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001919', 'straightaway', '/ˌstreɪtəˈweɪ/', 'adverb', 'imediatamente', 'She recognized him straightaway.', 'Ela o reconheceu imediatamente.', 'B2', array['narrative']),
('30000000-0000-0000-0000-000000001920', 'in the aftermath', '/ɪn ðə ˈæftərmæθ/', 'phrase', 'no rescaldo', 'In the aftermath of the storm, the town began to rebuild.', 'No rescaldo da tempestade, a cidade começou a se reconstruir.', 'B2', array['narrative']);

