-- Lição 316: Conjunções de tempo (by the time, no sooner...than, as soon as, once, while, beforehand)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000316', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001891", "show_image": false}'),
('20000000-0000-0000-0000-000000000316', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001893", "show_image": false}'),
('20000000-0000-0000-0000-000000000316', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001895", "show_image": false}'),
('20000000-0000-0000-0000-000000000316', 'multiple_choice', 4, '{"question": "___ we arrived, the meeting had already started.", "audio_text": null, "options": ["By the time", "While", "Once"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000316', 'multiple_choice', 5, '{"question": "Call me ___ you get home.", "audio_text": null, "options": ["as soon as", "beforehand", "by the time"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000316', 'matching', 6, '{"pairs": [{"left": "by the time", "right": "quando"}, {"left": "no sooner...than", "right": "mal... quando"}, {"left": "as soon as", "right": "assim que"}, {"left": "once", "right": "assim que"}, {"left": "while", "right": "enquanto"}, {"left": "beforehand", "right": "de antemão"}]}'),
('20000000-0000-0000-0000-000000000316', 'fill_blank', 7, '{"sentence": "___ the report is finished, we can send it.", "options": ["Once", "Beforehand", "Ever since"], "correct": "Once", "translation": "Assim que o relatório estiver pronto, podemos enviá-lo."}'),
('20000000-0000-0000-0000-000000000316', 'fill_blank', 8, '{"sentence": "It is better to prepare ___.", "options": ["beforehand", "eventually", "gradually"], "correct": "beforehand", "translation": "É melhor se preparar de antemão."}'),
('20000000-0000-0000-0000-000000000316', 'word_order', 9, '{"words": ["She", "read", "a", "book", "while", "waiting", "for", "the", "bus"], "correct_sentence": "She read a book while waiting for the bus", "translation": "Ela leu um livro enquanto esperava o ônibus"}'),
('20000000-0000-0000-0000-000000000316', 'word_order', 10, '{"words": ["No", "sooner", "had", "she", "sat", "down", "than", "the", "phone", "rang"], "correct_sentence": "No sooner had she sat down than the phone rang", "translation": "Mal ela tinha se sentado quando o telefone tocou"}'),
('20000000-0000-0000-0000-000000000316', 'reading', 11, '{"passage": "Advanced time conjunctions help writers sequence events precisely. ''By the time'' compares two past actions: by the time we arrived, the meeting had already started. ''No sooner...than'' emphasizes how quickly one thing follows another: no sooner had she sat down than the phone rang. ''As soon as'' and ''once'' both introduce an immediate next step.", "translation": "Conjunções de tempo avançadas ajudam escritores a sequenciar eventos com precisão. ''By the time'' compara duas ações passadas: quando chegamos, a reunião já tinha começado. ''No sooner...than'' enfatiza a rapidez com que uma coisa segue outra: mal ela tinha se sentado quando o telefone tocou. ''As soon as'' e ''once'' introduzem um próximo passo imediato.", "question": "What does ''no sooner...than'' emphasize, according to the text?", "options": ["A distant future event", "How quickly one thing follows another", "A repeated action"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000316', 'listening', 12, '{"audio_text": "By the time we arrived, the meeting had already started. No sooner had she sat down than the phone rang. Call me as soon as you get home.", "question": "What had already started by the time they arrived, according to the audio?", "options": ["The meeting", "The call", "The trip"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000316', 'dictation', 13, '{"audio_text": "By the time we arrived, the meeting had already started.", "expected": "By the time we arrived, the meeting had already started."}'),
('20000000-0000-0000-0000-000000000316', 'typing', 14, '{"prompt_pt": "Traduza: ''Assim que ele chegou, a reunião já tinha terminado.''", "expected": "By the time he arrived, the meeting had already finished.", "ai_review": true}'),

-- Lição 317: Sequenciadores narrativos (in the meantime, eventually, immediately, shortly after, all of a sudden, from then on)
('20000000-0000-0000-0000-000000000317', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001897", "show_image": false}'),
('20000000-0000-0000-0000-000000000317', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001901", "show_image": false}'),
('20000000-0000-0000-0000-000000000317', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001902", "show_image": false}'),
('20000000-0000-0000-0000-000000000317', 'multiple_choice', 4, '{"question": "___, the lights went out.", "audio_text": null, "options": ["All of a sudden", "Beforehand", "Up until"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000317', 'multiple_choice', 5, '{"question": "She left the office ___ after the call.", "audio_text": null, "options": ["immediately", "eventually", "gradually"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000317', 'matching', 6, '{"pairs": [{"left": "in the meantime", "right": "enquanto isso"}, {"left": "eventually", "right": "eventualmente"}, {"left": "immediately", "right": "imediatamente"}, {"left": "shortly after", "right": "logo depois"}, {"left": "all of a sudden", "right": "de repente"}, {"left": "from then on", "right": "a partir daquele momento"}]}'),
('20000000-0000-0000-0000-000000000317', 'fill_blank', 7, '{"sentence": "___, they found a solution to the problem.", "options": ["Eventually", "Beforehand", "While"], "correct": "Eventually", "translation": "Eventualmente, eles encontraram uma solução para o problema."}'),
('20000000-0000-0000-0000-000000000317', 'fill_blank', 8, '{"sentence": "___, everything changed for the better.", "options": ["From then on", "In due course", "Once"], "correct": "From then on", "translation": "A partir daquele momento, tudo mudou para melhor."}'),
('20000000-0000-0000-0000-000000000317', 'word_order', 9, '{"words": ["Shortly", "after", "the", "announcement", "the", "stock", "price", "rose"], "correct_sentence": "Shortly after the announcement the stock price rose", "translation": "Logo depois do anúncio, o preço da ação subiu"}'),
('20000000-0000-0000-0000-000000000317', 'word_order', 10, '{"words": ["Dinner", "will", "be", "ready", "soon", "In", "the", "meantime", "relax"], "correct_sentence": "Dinner will be ready soon In the meantime relax", "translation": "O jantar vai ficar pronto logo. Enquanto isso, relaxe"}'),
('20000000-0000-0000-0000-000000000317', 'reading', 11, '{"passage": "Good storytelling relies on sequencing markers. While waiting for something to happen, a writer can say ''in the meantime''. To describe a sudden change, ''all of a sudden'' works well, and ''shortly after'' shows something that happened soon afterward. ''From then on'' signals a lasting change, and ''eventually'' shows the final outcome of a long process.", "translation": "Uma boa narrativa depende de marcadores de sequência. Enquanto espera algo acontecer, um escritor pode dizer ''in the meantime''. Para descrever uma mudança repentina, ''all of a sudden'' funciona bem, e ''shortly after'' mostra algo que aconteceu logo depois. ''From then on'' sinaliza uma mudança duradoura, e ''eventually'' mostra o resultado final de um processo longo.", "question": "What does ''from then on'' signal, according to the text?", "options": ["A sudden change", "A lasting change", "An immediate action"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000317', 'listening', 12, '{"audio_text": "All of a sudden, the lights went out. She left the office immediately after the call. Eventually, they found a solution to the problem.", "question": "What went out all of a sudden, according to the audio?", "options": ["The lights", "The phone", "The office"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000317', 'dictation', 13, '{"audio_text": "All of a sudden, the lights went out.", "expected": "All of a sudden, the lights went out."}'),
('20000000-0000-0000-0000-000000000317', 'typing', 14, '{"prompt_pt": "Traduza: ''Enquanto isso, ela esperava. De repente, o telefone tocou.''", "expected": "In the meantime, she waited. All of a sudden, the phone rang.", "ai_review": true}'),

-- Lição 318: Duração e simultaneidade (up until, ever since, in due course, sooner or later, at that point, at the same time)
('20000000-0000-0000-0000-000000000318', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001903", "show_image": false}'),
('20000000-0000-0000-0000-000000000318', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001904", "show_image": false}'),
('20000000-0000-0000-0000-000000000318', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001908", "show_image": false}'),
('20000000-0000-0000-0000-000000000318', 'multiple_choice', 4, '{"question": "___ last year, she had never traveled abroad.", "audio_text": null, "options": ["Up until", "Ever since", "Sooner or later"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000318', 'multiple_choice', 5, '{"question": "You cannot cook and answer emails ___.", "audio_text": null, "options": ["at the same time", "at that point", "in due course"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000318', 'matching', 6, '{"pairs": [{"left": "up until", "right": "até"}, {"left": "ever since", "right": "desde então"}, {"left": "in due course", "right": "no devido tempo"}, {"left": "sooner or later", "right": "mais cedo ou mais tarde"}, {"left": "at that point", "right": "naquele momento"}, {"left": "at the same time", "right": "ao mesmo tempo"}]}'),
('20000000-0000-0000-0000-000000000318', 'fill_blank', 7, '{"sentence": "The results will be announced ___.", "options": ["in due course", "up until", "at that point"], "correct": "in due course", "translation": "Os resultados serão anunciados no devido tempo."}'),
('20000000-0000-0000-0000-000000000318', 'fill_blank', 8, '{"sentence": "___, the truth always comes out.", "options": ["Sooner or later", "Ever since", "At the same time"], "correct": "Sooner or later", "translation": "Mais cedo ou mais tarde, a verdade sempre aparece."}'),
('20000000-0000-0000-0000-000000000318', 'word_order', 9, '{"words": ["At", "that", "point", "nobody", "knew", "what", "would", "happen", "next"], "correct_sentence": "At that point nobody knew what would happen next", "translation": "Naquele momento, ninguém sabia o que aconteceria a seguir"}'),
('20000000-0000-0000-0000-000000000318', 'word_order', 10, '{"words": ["They", "met", "in", "college", "and", "ever", "since", "they", "have", "been", "best", "friends"], "correct_sentence": "They met in college and ever since they have been best friends", "translation": "Eles se conheceram na faculdade, e desde então, são melhores amigos"}'),
('20000000-0000-0000-0000-000000000318', 'reading', 11, '{"passage": "Some expressions describe how long something lasts. ''Up until'' marks a limit in the past, while ''ever since'' shows something that continues from a past point to now. ''In due course'' and ''sooner or later'' both suggest something will happen eventually, without a fixed date. ''At that point'' and ''at the same time'' mark or compare specific moments in a story.", "translation": "Algumas expressões descrevem quanto tempo algo dura. ''Up until'' marca um limite no passado, enquanto ''ever since'' mostra algo que continua de um ponto passado até agora. ''In due course'' e ''sooner or later'' sugerem que algo vai acontecer eventualmente, sem uma data fixa. ''At that point'' e ''at the same time'' marcam ou comparam momentos específicos em uma história.", "question": "What does ''ever since'' show, according to the text?", "options": ["A limit in the past", "Something continuing from a past point to now", "A fixed future date"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000318', 'listening', 12, '{"audio_text": "Up until last year, she had never traveled abroad. They met in college, and ever since, they have been best friends. The results will be announced in due course.", "question": "When did she never travel abroad, up until, according to the audio?", "options": ["Last year", "Last month", "College"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000318', 'dictation', 13, '{"audio_text": "Sooner or later, the truth always comes out.", "expected": "Sooner or later, the truth always comes out."}'),
('20000000-0000-0000-0000-000000000318', 'typing', 14, '{"prompt_pt": "Traduza: ''Até aquele momento, ninguém sabia da decisão; desde então, tudo mudou.''", "expected": "Up until that point, nobody knew about the decision; ever since, everything has changed.", "ai_review": true}'),

-- Lição 319: Advérbios de sequência (simultaneously, gradually, abruptly, henceforth, previously, afterwards)
('20000000-0000-0000-0000-000000000319', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000001909", "show_image": false}'),
('20000000-0000-0000-0000-000000000319', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000001910", "show_image": false}'),
('20000000-0000-0000-0000-000000000319', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000001914", "show_image": false}'),
('20000000-0000-0000-0000-000000000319', 'multiple_choice', 4, '{"question": "The two events happened ___.", "audio_text": null, "options": ["simultaneously", "abruptly", "previously"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000319', 'multiple_choice', 5, '{"question": "The meeting ended ___.", "audio_text": null, "options": ["abruptly", "gradually", "henceforth"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000319', 'matching', 6, '{"pairs": [{"left": "simultaneously", "right": "simultaneamente"}, {"left": "gradually", "right": "gradualmente"}, {"left": "abruptly", "right": "abruptamente"}, {"left": "henceforth", "right": "doravante"}, {"left": "previously", "right": "anteriormente"}, {"left": "afterwards", "right": "depois"}]}'),
('20000000-0000-0000-0000-000000000319', 'fill_blank', 7, '{"sentence": "The building was ___ used as a warehouse.", "options": ["previously", "simultaneously", "henceforth"], "correct": "previously", "translation": "O prédio era anteriormente usado como depósito."}'),
('20000000-0000-0000-0000-000000000319', 'fill_blank', 8, '{"sentence": "___, all reports must be submitted online.", "options": ["Henceforth", "Previously", "Gradually"], "correct": "Henceforth", "translation": "Doravante, todos os relatórios devem ser enviados online."}'),
('20000000-0000-0000-0000-000000000319', 'word_order', 9, '{"words": ["The", "company", "gradually", "expanded", "into", "new", "markets"], "correct_sentence": "The company gradually expanded into new markets", "translation": "A empresa se expandiu gradualmente para novos mercados"}'),
('20000000-0000-0000-0000-000000000319', 'word_order', 10, '{"words": ["They", "had", "dinner", "and", "went", "to", "the", "cinema", "afterwards"], "correct_sentence": "They had dinner and went to the cinema afterwards", "translation": "Eles jantaram e foram ao cinema depois"}'),
('20000000-0000-0000-0000-000000000319', 'reading', 11, '{"passage": "Sequence adverbs give a story more precision. Two things can happen simultaneously, or change can happen gradually over time versus abruptly, all at once. ''Henceforth'' announces a new rule going forward, ''previously'' refers back to an earlier state, and ''afterwards'' simply describes what came next in the sequence.", "translation": "Advérbios de sequência dão mais precisão a uma história. Duas coisas podem acontecer simultaneously, ou uma mudança pode acontecer gradually ao longo do tempo, em vez de abruptly, tudo de uma vez. ''Henceforth'' anuncia uma nova regra daqui para frente, ''previously'' se refere a um estado anterior, e ''afterwards'' simplesmente descreve o que veio a seguir na sequência.", "question": "What does ''henceforth'' announce, according to the text?", "options": ["A past event", "A new rule going forward", "A sudden change"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000319', 'listening', 12, '{"audio_text": "The two events happened simultaneously. The company gradually expanded into new markets. The meeting ended abruptly.", "question": "How did the company expand, according to the audio?", "options": ["Gradually", "Abruptly", "Simultaneously"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000319', 'dictation', 13, '{"audio_text": "The meeting ended abruptly.", "expected": "The meeting ended abruptly."}'),
